def _cov_query(h, fn, p, cap):
    buf = (ctypes.c_double * cap)()
    n = fn(h, p, buf, cap)
    if n < 0:
        raise AraelError(n, _err(h))
    return buf


def _shape_1(buf):
    return float(buf[0])


def _shape_2(buf):
    return _m.matrix2d.from_elements(buf[0], buf[1], buf[2], buf[3])


def _shape_3(buf):
    return _m.matrix3d.from_elements(*[buf[i] for i in range(9)])


def _shape_n(buf, n):
    return tuple(tuple(buf[r * n + c] for c in range(n)) for r in range(n))


class Covariance:
    """Covariance prepared at the solution; per-entity queries
    (marginal/conditional by param count: 1 -> float, 2/3 ->
    matrix2d/3d, larger -> row-major tuples). Valid until the model is
    dropped or reassembled."""

    __slots__ = ("_h",)

    def __init__(self, h):
        self._h = h

    def marginal(self, e):
        """The entity's marginal covariance block."""
        if isinstance(e, Cell):
            return (_shape_1)(_cov_query(self._h, _f.decay_cell_marginal_cov, e._p, 1))
        raise TypeError("no marginal for %r" % (e,))

    def conditional(self, e):
        """Conditional covariance (all other parameters fixed)."""
        if isinstance(e, Cell):
            return (_shape_1)(_cov_query(self._h, _f.decay_cell_conditional_cov, e._p, 1))
        raise TypeError("no conditional for %r" % (e,))

    def std_dev(self, e):
        """Per-parameter standard deviations (every CovMode, incl.
        TriDiagonal)."""
        if isinstance(e, Cell):
            return list(_cov_query(self._h, _f.decay_cell_std_dev, e._p, 1))
        raise TypeError("no std_dev for %r" % (e,))
    def _cross_cell_cell(self, a, b):
        buf = (ctypes.c_double * 1)()
        rows = _f.decay_cell_cell_cross_cov(self._h, a._p, b._p, buf, 1)
        if rows < 0:
            raise AraelError(rows, _err(self._h))
        return tuple(tuple(buf[r * 1 + c] for c in range(1))
                     for r in range(rows))

    def cross(self, a, b):
        """Row-major cross-covariance block between two entities."""
        if isinstance(a, Cell) and isinstance(b, Cell):
            return self._cross_cell_cell(a, b)
        raise TypeError("no cross-covariance for %r x %r" % (a, b))


class DecayCellsVec:
    """View of `cells` (vec of Cell); wrappers stay valid per the
    C++ contract, mutating while iterating is undefined."""

    __slots__ = ("_p",)

    def __init__(self, p):
        self._p = p

    def __len__(self):
        return _f.decay_cells_len(self._p)

    def reserve(self, additional):
        _f.decay_cells_reserve(self._p, additional)

    def __getitem__(self, i):
        if isinstance(i, CellRef):
            return Cell(lambda r=i.raw: _f.decay_cells_get(self._p, r))
        n = len(self)
        if i < 0:
            i += n
        if not 0 <= i < n:
            raise IndexError(i)
        return Cell(lambda i=i: _f.decay_cells_at(self._p, i))

    def __iter__(self):
        for i in range(len(self)):
            yield Cell(lambda i=i: _f.decay_cells_at(self._p, i))

    def clear(self):
        _f.decay_cells_clear(self._p)

    def truncate(self, n):
        _f.decay_cells_truncate(self._p, n)

    def push(self):
        _f.decay_cells_push(self._p)
        return self[self.ref_at(len(self) - 1)]

    def pop(self):
        """Drops the last element; False when already empty."""
        return _f.decay_cells_pop(self._p)

    def get(self, r):
        return Cell(lambda k=_raw(r): _f.decay_cells_get(self._p, k))

    def __contains__(self, r):
        return _f.decay_cells_contains(self._p, _raw(r))

    def try_get(self, r):
        """The element, or None for a stale or foreign ref."""
        p = _f.decay_cells_try_get(self._p, _raw(r))
        return Cell(lambda k=_raw(r): _f.decay_cells_get(self._p, k)) if p else None

    def ref_at(self, i):
        return CellRef(_f.decay_cells_ref_at(self._p, i))

    def first_ref(self):
        """Ref of the first element; null when empty."""
        return CellRef(_f.decay_cells_first_ref(self._p))

    def last_ref(self):
        """Ref of the last element; null when empty."""
        return CellRef(_f.decay_cells_last_ref(self._p))


class Decay:
    """The model. Owns the underlying Rust instance; free() (or GC)
    releases it. One model, one thread."""

    def __init__(self):
        load()
        self._p = _f.decay_new()

    def free(self):
        if self._p:
            _f.decay_free(self._p)
            self._p = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def _solved(self, code, res):
        if code < 0:
            raise AraelError(code, _err(self._p))
        return res

    def solve_dense(self, cfg=None):
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.decay_solve_dense(self._p, ctypes.byref(cfg),
                                     ctypes.byref(r)), r)

    def solve_sparse(self, cfg=None):
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.decay_solve_sparse(self._p, ctypes.byref(cfg),
                                      ctypes.byref(r)), r)

    def solve_band(self, kd, cfg=None):
        """Band Cholesky solve; kd is the half-bandwidth in scalar
        parameters."""
        cfg = cfg if cfg is not None else LmConfig()
        r = LmResult()
        return self._solved(
            _f.decay_solve_band(self._p, kd, ctypes.byref(cfg),
                                    ctypes.byref(r)), r)

    def assemble_covariance(self, mode=CovMode.ALL_MARGINALS):
        code = _f.decay_assemble_covariance(self._p, int(mode))
        if code != 0:
            raise AraelError(code, _err(self._p))
        return Covariance(self._p)

    def cost(self):
        """Total cost at the current parameter values (no solve)."""
        return _f.decay_cost(self._p)

    def validate(self):
        """Empty string when the model is clean, the diagnostic text
        otherwise."""
        return _f.decay_validate(self._p).decode()

    def last_error(self):
        return _err(self._p)

    def last_report(self):
        """Text report of the last completed solve; '' before one."""
        return _f.decay_last_report(self._p, False).decode()

    def last_pretty_report(self):
        """last_report() with colour and box-drawing glyphs."""
        return _f.decay_last_report(self._p, True).decode()

    @property
    def cells(self):
        return DecayCellsVec(self._p)

